	CGLContextObj context=nullptr;GLuint programs[8]{},fbo=0,color=0,depth=0,vao=0,buffers[3]{};std::map<std::string,GLuint> images;
	GLReference(const NativeProjectileEffectFrame& frame){CGLPixelFormatAttribute attr[]={kCGLPFAAccelerated,kCGLPFAOpenGLProfile,CGLPixelFormatAttribute(kCGLOGLPVersion_3_2_Core),CGLPixelFormatAttribute(0)};CGLPixelFormatObj format=nullptr;GLint n=0;Check(CGLChoosePixelFormat(attr,&format,&n)==kCGLNoError&&format,"Original GLSL reference pixel format unavailable");auto result=CGLCreateContext(format,nullptr,&context);CGLDestroyPixelFormat(format);Check(result==kCGLNoError&&context,"Original GLSL reference context unavailable");Check(CGLSetCurrentContext(context)==kCGLNoError,"Original GLSL reference activation");
		for(const auto& d:frame.draws){const unsigned kind=unsigned(d.program);auto adapt=[&](const char* stage){auto source=Read(work+"/original-shaders/"+std::to_string(kind)+stage+".glsl");auto at=source.find("#version 420");Check(at!=std::string::npos,"Original GLSL version identity");source.replace(at,12,"#version 410");for(const char* extension:{"#extension GL_ARB_uniform_buffer_object : require","#extension GL_ARB_shading_language_420pack: require"}){at=source.find(extension);Check(at!=std::string::npos,"Original GLSL extension identity");source.replace(at,strlen(extension),"");}at=source.find("//__DEFINES__");Check(at!=std::string::npos,"Original GLSL parameter injection");std::ostringstream config;config<<std::setprecision(9)<<std::showpoint;for(const auto&[name,value]:d.parameters)config<<"#define "<<name<<' '<<value<<'\n';source.replace(at,strlen("//__DEFINES__"),config.str());at=source.find("//__ENGINEUNIFORMBUFFERDEFS__");Check(at!=std::string::npos,"Original GLSL camera/time injection");source.replace(at,strlen("//__ENGINEUNIFORMBUFFERDEFS__"),"uniform mat4 cameraViewProj,cameraViewInv;uniform vec4 timeInfo;");return source;};auto v=Shader(GL_VERTEX_SHADER,adapt(".vert")),p=Shader(GL_FRAGMENT_SHADER,adapt(".frag"));auto program=glCreateProgram();programs[kind]=program;glAttachShader(program,v);glAttachShader(program,p);glLinkProgram(program);glDeleteShader(v);glDeleteShader(p);GLint ok=0;glGetProgramiv(program,GL_LINK_STATUS,&ok);if(!ok){char log[8192]{};glGetProgramInfoLog(program,sizeof(log),nullptr,log);throw std::runtime_error(log);}}
		glGenFramebuffers(1,&fbo);glBindFramebuffer(GL_FRAMEBUFFER,fbo);glGenTextures(1,&color);glBindTexture(GL_TEXTURE_2D,color);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA8,width,height,0,GL_RGBA,GL_UNSIGNED_BYTE,nullptr);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_TEXTURE_2D,color,0);glGenRenderbuffers(1,&depth);glBindRenderbuffer(GL_RENDERBUFFER,depth);glRenderbufferStorage(GL_RENDERBUFFER,GL_DEPTH_COMPONENT32F,width,height);glFramebufferRenderbuffer(GL_FRAMEBUFFER,GL_DEPTH_ATTACHMENT,GL_RENDERBUFFER,depth);Check(glCheckFramebufferStatus(GL_FRAMEBUFFER)==GL_FRAMEBUFFER_COMPLETE,"Original projectile oracle FBO");glGenVertexArrays(1,&vao);glGenBuffers(3,buffers);
	}
	~GLReference(){if(context){CGLSetCurrentContext(context);glDeleteProgram(programs[0]);for(unsigned n=1;n<8;++n)glDeleteProgram(programs[n]);glDeleteFramebuffers(1,&fbo);glDeleteTextures(1,&color);glDeleteRenderbuffers(1,&depth);glDeleteVertexArrays(1,&vao);glDeleteBuffers(3,buffers);for(auto[n,t]:images)glDeleteTextures(1,&t);CGLSetCurrentContext(nullptr);CGLDestroyContext(context);}}
	std::vector<uint8_t> Render(const NativeProjectileEffectFrame& f,float clearDepth){CGLSetCurrentContext(context);glBindFramebuffer(GL_FRAMEBUFFER,fbo);glViewport(0,0,width,height);glDisable(GL_SCISSOR_TEST);glDisable(GL_DITHER);glDisable(GL_CULL_FACE);glDisable(GL_MULTISAMPLE);glColorMask(true,true,true,true);glDepthMask(true);glClearColor(.02f,.03f,.04f,0);glClearDepth(clearDepth);glClear(GL_COLOR_BUFFER_BIT|GL_DEPTH_BUFFER_BIT);glEnable(GL_BLEND);glBlendFunc(GL_ONE,GL_ONE);glEnable(GL_DEPTH_TEST);glDepthFunc(GL_LEQUAL);glDepthMask(false);
