			glBindVertexArray(vao);glBindBuffer(GL_ARRAY_BUFFER,buffers[0]);glBufferData(GL_ARRAY_BUFFER,d.vertices->bytes.size(),d.vertices->bytes.data(),GL_STATIC_DRAW);glEnableVertexAttribArray(0);glVertexAttribPointer(0,4,GL_FLOAT,false,16,nullptr);glVertexAttribDivisor(0,0);glBindBuffer(GL_ARRAY_BUFFER,buffers[1]);glBufferData(GL_ARRAY_BUFFER,d.instances->bytes.size(),d.instances->bytes.data(),GL_STATIC_DRAW);for(unsigned n=1;n<=5;++n){if(n*16<=d.instances->layout.stride){glEnableVertexAttribArray(n);glVertexAttribPointer(n,4,GL_FLOAT,false,d.instances->layout.stride,reinterpret_cast<const void*>(uintptr_t((n-1)*16)));glVertexAttribDivisor(n,1);}else glDisableVertexAttribArray(n);}if(d.indexed){glBindBuffer(GL_ELEMENT_ARRAY_BUFFER,buffers[2]);glBufferData(GL_ELEMENT_ARRAY_BUFFER,d.indices->bytes.size(),d.indices->bytes.data(),GL_STATIC_DRAW);glDrawElementsInstanced(GL_TRIANGLES,6,GL_UNSIGNED_SHORT,nullptr,d.instanceCount);}else glDrawArraysInstanced(GL_TRIANGLES,0,6,d.instanceCount);
		}std::vector<uint8_t>b(width*height*4),top(b.size());glReadPixels(0,0,width,height,GL_RGBA,GL_UNSIGNED_BYTE,b.data());Check(glGetError()==GL_NO_ERROR,"Original GLSL GL error");for(unsigned y=0;y<height;++y)std::copy_n(b.data()+size_t(y)*width*4,width*4,top.data()+size_t(height-1-y)*width*4);return top;}
