std::vector<uint8_t> Native(ProjectileEffectsGPU&gpu,const NativeProjectileEffectFrame&f,float clearDepth,bool omit){RuntimeLease lease;const auto start=Clock::now();auto descriptor=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatRGBA8Unorm width:width height:height mipmapped:NO];descriptor.storageMode=MTLStorageModeShared;descriptor.usage=MTLTextureUsageRenderTarget|MTLTextureUsageShaderRead;auto color=[lease.Device()newTextureWithDescriptor:descriptor];Check(color!=nil,"Native oracle color");lease.AddAllocation(color);descriptor=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatDepth32Float width:width height:height mipmapped:NO];descriptor.storageMode=MTLStorageModePrivate;descriptor.usage=MTLTextureUsageRenderTarget|MTLTextureUsageShaderRead;auto depth=[lease.Device()newTextureWithDescriptor:descriptor];Check(depth!=nil,"Native oracle depth");lease.AddAllocation(depth);auto readback=[lease.Device()newBufferWithLength:width*height*4 options:MTLResourceStorageModeShared];Check(readback!=nil,"Native depth copy");lease.AddAllocation(readback);WorldCamera view;view.clipDepth=ClipDepthConvention::MinusOneToOne;double ms=0;auto prepared=omit?std::unique_ptr<PreparedProjectileEffects>{}:gpu.Prepare(lease,f,view,MTLPixelFormatRGBA8Unorm,MTLPixelFormatDepth32Float,true,ms);auto pass=[MTL4RenderPassDescriptor new];pass.renderTargetWidth=width;pass.renderTargetHeight=height;pass.colorAttachments[0].texture=color;pass.colorAttachments[0].loadAction=MTLLoadActionClear;pass.colorAttachments[0].storeAction=MTLStoreActionStore;pass.colorAttachments[0].clearColor=MTLClearColorMake(.02,.03,.04,0);pass.depthAttachment.texture=depth;pass.depthAttachment.loadAction=MTLLoadActionClear;pass.depthAttachment.storeAction=MTLStoreActionStore;pass.depthAttachment.clearDepth=clearDepth;lease.CommitResources();auto cmd=lease.Begin("Original Beam/Plasma CGL/Metal pixels");if(prepared)prepared->EncodeDependencies(cmd);auto e=[cmd renderCommandEncoderWithDescriptor:pass];Check(e!=nil,"Native oracle encoder");[e setViewport:MTLViewport{0,0,width,height,0,1}];[e setScissorRect:MTLScissorRect{0,0,width,height}];if(prepared)for(size_t n=0;n<prepared->DrawCount();++n){Check(prepared->SequenceAt(n)==f.draws[n].sequence,"Actual world draw sequence retained");prepared->EncodeDraw(n,e);}[e endEncoding];auto copy=[cmd computeCommandEncoder];Check(copy!=nil,"Native depth readback encoder");[copy barrierAfterQueueStages:MTLStageAll beforeStages:MTLStageBlit visibilityOptions:MTL4VisibilityOptionDevice];[copy copyFromTexture:depth sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(0,0,0) sourceSize:MTLSizeMake(width,height,1) toBuffer:readback destinationOffset:0 destinationBytesPerRow:width*4 destinationBytesPerImage:0];[copy endEncoding];lease.SubmitAndWait(start,renders++);if(prepared)prepared->DidComplete();for(unsigned n=0;n<width*height;++n){float z;memcpy(&z,static_cast<const uint8_t*>(readback.contents)+n*4,4);Check(z==clearDepth,"Additive original effects must not write world depth");}double read=0;return lease.Readback(color,width,height,read);}
}
int main(int argc,char**argv){@autoreleasepool{try{Check(argc>=3,"usage effects-gpu work output.json [omit|wrong-time]");work=argv[1];auto baseline=Frame();GLReference reference(baseline);ProjectileEffectsGPU gpu;{RuntimeLease lease;double ms=0;gpu.Initialize(lease,MTLPixelFormatRGBA8Unorm,true,ms);}const std::string fault=argc>3?argv[3]:"";unsigned maxError=0,different=0,visible=0;std::ostringstream records;unsigned number=0;
	for(unsigned variant=0;variant<4;++variant)for(unsigned mode=0;mode<10;++mode){auto f=baseline;if(mode<8){auto found=std::find_if(f.draws.begin(),f.draws.end(),[&](const auto&d){return unsigned(d.program)==mode;});auto d=*found;f.draws={d};}else if(mode==8)f.draws.resize(4);else f.draws.erase(f.draws.begin(),f.draws.begin()+4);f.timeInfo[2]=variant==0?0.f:variant==1?.37f:variant==2?2.15f:3.3416667f;for(auto&d:f.draws){if(unsigned(d.program)<4&&variant==2)SetInstance(d,7,.91f);if(unsigned(d.program)<4&&variant==1)SetInstance(d,17,1);if(unsigned(d.program)>=4){SetInstance(d,12,.4f);SetInstance(d,13,.3f);SetInstance(d,14,.8660254f);if(variant==1){SetInstance(d,12,0);SetInstance(d,13,0);SetInstance(d,14,-1);}}}const float depth=variant==3?.2f:.95f;auto gl=reference.Render(f,depth);auto nativeFrame=f;if(fault=="wrong-time")nativeFrame.timeInfo[2]=nativeFrame.timeInfo[0];auto metal=Native(gpu,nativeFrame,depth,fault=="omit");unsigned local=0,deltaCount=0,painted=0;for(size_t n=0;n<gl.size();++n){unsigned delta=std::abs(int(gl[n])-int(metal[n]));local=std::max(local,delta);deltaCount+=delta!=0;if(n%4<3&&gl[n]!=uint8_t(n%4==0?5:n%4==1?8:10))++painted;}maxError=std::max(maxError,local);different+=deltaCount;visible+=painted;if(number++)records<<',';records<<"{\"variant\":"<<variant<<",\"mode\":"<<mode<<",\"maxChannelError\":"<<local<<",\"differentChannels\":"<<deltaCount<<",\"paintedChannels\":"<<painted<<'}';std::cerr<<"case "<<variant<<' '<<mode<<" max "<<local<<" different "<<deltaCount<<'\n';Check(local<=2,"Original GLSL/Metal pixel tolerance exceeded");}
	Check(visible>1000,"Pixel oracle needs actual visible original effects");std::ofstream out(argv[2]);out<<"{\"status\":\"PASS\",\"checks\":"<<checks<<",\"renders\":"<<renders<<",\"maxChannelError\":"<<maxError<<",\"differentChannels\":"<<different<<",\"paintedChannels\":"<<visible<<",\"cases\":["<<records.str()<<"]}\n";std::cout<<"PASS "<<renders<<" original GLSL/Metal renders / "<<checks<<" checks / max "<<maxError<<'\n';return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}}
